// LSH room-service.escalation → an urgent "please follow up" message.
const b = $input.first().json.body || {};
const d = b.data || {};
const o = d.order || {};
const summary = '⚠️ UNACKNOWLEDGED ' + d.waitingMinutes + ' min — room ' + (o.room || '?') + ', ' + o.total + ' ' + o.currency + '. Please follow up.';
return [{ json: { event: b.event, hub: b.hub, summary, waitingMinutes: d.waitingMinutes, order: o } }];
